mapper.select:
SELECT ra.id, ra.patient_id, p.name AS patient_name, ra.risk_level, rlc.level_name AS risk_level_name, ra.assessment_date, ra.assessor_id, u.name AS assessor_name, ra.assessment_result, ra.remarks FROM risk_assessment ra LEFT JOIN patient p ON ra.patient_id = p.id LEFT JOIN user u ON ra.assessor_id = u.id LEFT JOIN risk_level_config rlc ON ra.risk_level = rlc.level_code
AND ra.patient_id = #{patientId}
AND ra.risk_level = #{riskLevel}
ORDER BY ra.assessment_date DESC, ra.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM risk_assessment ra


        AND ra.patient_id = #{patientId}


        AND ra.risk_level = #{riskLevel}
